def chunk(text, size=400, overlap=80):
    if size <= 0: raise ValueError('size must be > 0')
    step = max(1, size - overlap)
    out = []
    for i in range(0, len(text), step):
        piece = text[i:i + size]
        if not piece: break
        out.append(piece)
        if i + size >= len(text): break
    return out

def cosine(a, b):
    if len(a) != len(b): raise ValueError('dimension mismatch')
    dot = sum(x * y for x, y in zip(a, b))
    na = sum(x * x for x in a) ** 0.5
    nb = sum(y * y for y in b) ** 0.5
    if na == 0 or nb == 0: return 0.0
    return dot / (na * nb)

import math
from collections import Counter

def idf(docs, term):
    n = sum(1 for d in docs if term in d)
    return math.log((1 + len(docs)) / (1 + n)) + 1

def score(query, doc):
    terms = query.lower().split()
    tf = Counter(doc.lower().split())
    return sum(tf[t] * idf([doc], t) for t in terms)

import json

def parse_json(text):
    text = text.strip()
    if text.startswith('```'):
        text = text.split('```')[1]
        if text.lower().startswith('json'):
            text = text[4:]
    start, end = text.find('{'), text.rfind('}')
    if start == -1 or end == -1: raise ValueError('no JSON object found')
    return json.loads(text[start:end + 1])

import random, time

def with_retry(fn, attempts=4, base=0.5, retriable=(TimeoutError, ConnectionError)):
    for i in range(attempts):
        try:
            return fn()
        except retriable as e:
            if i == attempts - 1: raise
            time.sleep(base * (2 ** i) + random.uniform(0, base))

def dedupe(chunks):
    best = {}
    for c in chunks:
        cur = best.get(c['id'])
        if cur is None or c['score'] > cur['score']:
            best[c['id']] = c
    return sorted(best.values(), key=lambda c: -c['score'])

def rrf(lists, k=60):
    scores = {}
    for ranked in lists:
        for rank, doc_id in enumerate(ranked, start=1):
            scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (k + rank)
    return sorted(scores.items(), key=lambda kv: -kv[1])

def recall_at_k(gold_ids, retrieved_ids, k=5):
    top = set(retrieved_ids[:k])
    gold = set(gold_ids)
    if not gold: return 1.0
    return len(top & gold) / len(gold)

import re

STOP = {'the','a','an','is','are','of','to','and','in','for','on','with','it','this','that'}

def faithfulness(answer, context):
    words = [w for w in re.findall(r'[a-z0-9]+', answer.lower()) if w not in STOP]
    if not words: return 1.0
    ctx = set(re.findall(r'[a-z0-9]+', context.lower()))
    return sum(1 for w in words if w in ctx) / len(words)

import hashlib

class MockLLM:
    def __init__(self, answers=None):
        self.answers = answers or {}
        self.calls = []
    def complete(self, prompt):
        self.calls.append(prompt)
        key = hashlib.sha256(prompt.encode()).hexdigest()[:8]
        return self.answers.get(key, f'mock-answer-{key}')

import hashlib

def embed_cached(text, embed_fn, cache):
    key = hashlib.sha256(text.encode()).hexdigest()
    if key not in cache:
        cache[key] = embed_fn(text)
    return cache[key]

def split_markdown(md):
    sections, cur = [], {'title': 'intro', 'body': []}
    for line in md.splitlines():
        if line.startswith('#'):
            if cur['body'] or cur['title'] != 'intro': sections.append(cur)
            cur = {'title': line.lstrip('# ').strip(), 'body': []}
        else:
            cur['body'].append(line)
    sections.append(cur)
    return [{'title': s['title'], 'text': '\n'.join(s['body']).strip()} for s in sections if s['body']]

ROUTES = [
    ('refund', ('refund', 'paise wapas', 'money back')),
    ('order_status', ('order', 'delivery', 'kahan hai')),
    ('invoice', ('invoice', 'bill', 'receipt')),
]

def route(text):
    low = text.lower()
    for tool, words in ROUTES:
        if any(w in low for w in words):
            return tool
    return 'handoff_to_human'

import re

def stream_consume(tokens):
    buf = []
    for tok in tokens:
        buf.append(tok)
        if re.search(r'\[[\w-]+\]', tok):
            pass
    text = ''.join(buf)
    citations = sorted(set(re.findall(r'\[([\w-]+)\]', text)))
    return {'text': text, 'citations': citations}

def search(query_vec, items, k=5, where=None):
    def keep(item):
        if not where: return True
        meta = item.get('meta', {})
        return all(meta.get(key) == val for key, val in where.items())
    candidates = [it for it in items if keep(it)]
    ranked = sorted(candidates, key=lambda it: -cosine(query_vec, it['vec']))
    return ranked[:k]
